param([string]$InstallDir = 'C:\TelegramAssistant')
$ErrorActionPreference = 'Stop'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$identity = [Security.Principal.WindowsIdentity]::GetCurrent()
$principal = New-Object Security.Principal.WindowsPrincipal($identity)
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw 'Run PowerShell as administrator.' }
Write-Host 'Four conversation features setup v1 starting.'

$root = [IO.Path]::GetFullPath($InstallDir)
$botPath = Join-Path $root 'bot.py'
$intelligencePath = Join-Path $root 'intelligence.py'
$python = Join-Path $root 'runtime\python.exe'
$stage = Join-Path $root 'four-features-update'
$taskName = 'TelegramPersonalAssistant'
foreach ($path in @($botPath, $python)) { if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { throw "Missing file: $path" } }
if (-not (Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue)) { throw 'Bot task not found.' }
New-Item -ItemType Directory -Path $stage -Force | Out-Null

$botPayload = @'

'@
$intelligencePayload = @'

'@
$newBot = Join-Path $stage 'bot.py'
$newIntelligence = Join-Path $stage 'intelligence.py'
[IO.File]::WriteAllBytes($newBot, [Convert]::FromBase64String($botPayload.Trim()))
[IO.File]::WriteAllBytes($newIntelligence, [Convert]::FromBase64String($intelligencePayload.Trim()))
$oldBot = [IO.File]::ReadAllText($botPath, [Text.Encoding]::UTF8)
$ownerMatch = [regex]::Match($oldBot, 'owner\s*=\s*os\.getenv\("TELEGRAM_OWNER_ID",\s*"([0-9]+)"\)')
if ($ownerMatch.Success) {
    $newBotText = [IO.File]::ReadAllText($newBot, [Text.Encoding]::UTF8)
    $ownerPlaceholder = 'owner = os.getenv("TELEGRAM_OWNER_ID")'
    if (-not $newBotText.Contains($ownerPlaceholder)) { throw 'Owner setting was not found in the new bot. No files were changed.' }
    $newBotText = $newBotText.Replace($ownerPlaceholder, ('owner = os.getenv("TELEGRAM_OWNER_ID", "' + $ownerMatch.Groups[1].Value + '")'))
    [IO.File]::WriteAllText($newBot, $newBotText, [Text.UTF8Encoding]::new($false))
} elseif (-not $env:TELEGRAM_OWNER_ID) {
    throw 'Set TELEGRAM_OWNER_ID before installation; the existing bot has no owner ID. No files were changed.'
}
$ErrorActionPreference = 'Continue'
& $python -m py_compile $newBot $newIntelligence
$compileExit = $LASTEXITCODE
$ErrorActionPreference = 'Stop'
if ($compileExit -ne 0) { throw 'New Python files failed syntax check; existing files were not changed.' }

$requirements = Join-Path $stage 'ocr-requirements.txt'
[IO.File]::WriteAllText($requirements, "rapidocr==3.10.0`nopencv-python-headless==4.11.0.86`nnumpy==1.26.4`n", [Text.Encoding]::ASCII)
Write-Host 'Downloading OCR dependencies through Happ. The bot keeps running during download.'
$ErrorActionPreference = 'Continue'
& $python -m pip download --disable-pip-version-check --only-binary=:all: --dest $stage --proxy http://127.0.0.1:10809 -r $requirements
$downloadExit = $LASTEXITCODE
$ErrorActionPreference = 'Stop'
if ($downloadExit -ne 0) { throw 'Dependency download failed; existing bot was not changed.' }

function Stop-ProcessAsSystem([int]$ProcessId) {
    if (-not (Get-Process -Id $ProcessId -ErrorAction SilentlyContinue)) { return }
    $cleanupTask = "TelegramFeaturesCleanup$ProcessId"
    $action = New-ScheduledTaskAction -Execute (Join-Path $env:WINDIR 'System32\taskkill.exe') -Argument "/F /PID $ProcessId"
    $trigger = New-ScheduledTaskTrigger -Once -At (Get-Date).AddMinutes(10)
    $system = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
    Register-ScheduledTask -TaskName $cleanupTask -Action $action -Trigger $trigger -Principal $system -Force | Out-Null
    try {
        Start-ScheduledTask -TaskName $cleanupTask
        for ($attempt = 0; $attempt -lt 12; $attempt++) {
            Start-Sleep -Seconds 1
            if (-not (Get-Process -Id $ProcessId -ErrorAction SilentlyContinue)) { break }
        }
    } finally {
        Unregister-ScheduledTask -TaskName $cleanupTask -Confirm:$false -ErrorAction SilentlyContinue
    }
    if (Get-Process -Id $ProcessId -ErrorAction SilentlyContinue) { throw "Could not stop process $ProcessId." }
}

$backupBot = $botPath + '.before-four-features'
$backupIntelligence = $intelligencePath + '.before-four-features'
$taskDisabled = $false
$botReplaced = $false
try {
    Disable-ScheduledTask -TaskName $taskName | Out-Null
    $taskDisabled = $true
    Stop-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 2
    $botPids = @(Get-CimInstance Win32_Process -Filter "Name='python.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.CommandLine -like ('*' + $botPath + '*') } | Select-Object -ExpandProperty ProcessId)
    $modelPids = @(Get-NetTCPConnection -LocalPort 18765 -State Listen -ErrorAction SilentlyContinue | Select-Object -ExpandProperty OwningProcess -Unique)
    foreach ($processId in $botPids) { Stop-ProcessAsSystem ([int]$processId) }
    foreach ($processId in $modelPids) {
        $process = Get-Process -Id $processId -ErrorAction SilentlyContinue
        if ($process -and $process.ProcessName -eq 'llama-server') { Stop-ProcessAsSystem ([int]$processId) }
    }

    Write-Host 'Installing OCR while keeping NumPy pinned to 1.26.4...'
    $ErrorActionPreference = 'Continue'
    & $python -m pip install --disable-pip-version-check --no-index --find-links $stage -r $requirements
    $installExit = $LASTEXITCODE
    $ErrorActionPreference = 'Stop'
    if ($installExit -ne 0) { throw 'OCR installation failed. The previous bot will be restarted.' }
    $smoke = Join-Path $stage 'smoke.py'
    [IO.File]::WriteAllText($smoke, @'
import numpy
from faster_whisper import WhisperModel
from rapidocr import RapidOCR
from PIL import Image
from pathlib import Path
assert numpy.__version__ == "1.26.4", numpy.__version__
engine = RapidOCR(params={"Rec.lang_type": "cyrillic", "Rec.ocr_version": "PP-OCRv5", "Rec.model_type": "mobile"})
picture = Path(__file__).with_name("ocr-smoke.png")
Image.new("RGB", (128, 64), "white").save(picture)
engine(str(picture))
print("NumPy, speech recognition and Cyrillic OCR loaded successfully", flush=True)
'@, [Text.Encoding]::ASCII)
    $env:HTTPS_PROXY = 'http://127.0.0.1:10809'
    $env:HTTP_PROXY = 'http://127.0.0.1:10809'
    $ErrorActionPreference = 'Continue'
    & $python $smoke
    $smokeExit = $LASTEXITCODE
    $ErrorActionPreference = 'Stop'
    if ($smokeExit -ne 0) { throw 'OCR or voice dependency test failed. The previous bot will be restarted.' }

    Copy-Item -LiteralPath $botPath -Destination $backupBot -Force
    if (Test-Path -LiteralPath $intelligencePath) { Copy-Item -LiteralPath $intelligencePath -Destination $backupIntelligence -Force }
    $botReplaced = $true
    Copy-Item -LiteralPath $newIntelligence -Destination $intelligencePath -Force
    Copy-Item -LiteralPath $newBot -Destination $botPath -Force
    Enable-ScheduledTask -TaskName $taskName | Out-Null
    $taskDisabled = $false
    Start-ScheduledTask -TaskName $taskName
} catch {
    $failure = $_
    if ($botReplaced) {
        Copy-Item -LiteralPath $backupBot -Destination $botPath -Force -ErrorAction SilentlyContinue
        if (Test-Path -LiteralPath $backupIntelligence) { Copy-Item -LiteralPath $backupIntelligence -Destination $intelligencePath -Force -ErrorAction SilentlyContinue }
        else { Remove-Item -LiteralPath $intelligencePath -Force -ErrorAction SilentlyContinue }
    }
    if ($taskDisabled) { Enable-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue | Out-Null }
    Start-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue
    throw $failure
}
Write-Host 'All four features installed. No token entry was needed.'
Write-Host 'Wait about one minute, then test /start, /find, /remember and /mission.'
